import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1788283422000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><h2 id="what-the-credential-can-do" tabindex="-1">What the credential can do <a class="header-anchor" href="#what-the-credential-can-do" aria-label="Permalink to “What the credential can do”">​</a></h2><p>The blast radius depends entirely on which kind you use, and the three differ enormously:</p><table tabindex="0"><thead><tr><th>Credential</th><th>Sees</th></tr></thead><tbody><tr><td>Service account</td><td>Only the properties it was explicitly added to. Revocable on its own</td></tr><tr><td>OAuth2 refresh token</td><td>Everything the consenting person sees, in every account. Scopes fixed at consent</td></tr><tr><td>Application default</td><td>Whatever the machine is logged into — usually the widest</td></tr></tbody></table><p>The service account is the recommended one for exactly this reason. Nothing about this server makes an OAuth token safer than the account behind it.</p><h2 id="scopes-follow-the-tools" tabindex="-1">Scopes follow the tools <a class="header-anchor" href="#scopes-follow-the-tools" aria-label="Permalink to “Scopes follow the tools”">​</a></h2><p>The OAuth scopes requested at startup are derived from the tools that are actually registered — see <code>scopesFor</code> in <code>src/auth.ts</code>. Denying the Indexing tools means the Indexing scope is never requested.</p><p><code>GSC_READ_ONLY=true</code> additionally swaps <code>webmasters</code> for <code>webmasters.readonly</code>, which makes writing impossible below the tool layer rather than only above it.</p><p>The one gap worth naming: Site Verification has no read-only scope. Google&#39;s <code>siteverification.verify_only</code> is write-only and cannot list, so the read tools there need the full scope. That is a limit of Google&#39;s scope design, not an oversight here.</p><h2 id="irreversible-operations-ask-a-person" tabindex="-1">Irreversible operations ask a person <a class="header-anchor" href="#irreversible-operations-ask-a-person" aria-label="Permalink to “Irreversible operations ask a person”">​</a></h2><p>Four tools put the question to a <strong>person</strong> before they act, through MCP elicitation — a dialog the model cannot answer on its behalf, and which nothing proceeds without:</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it costs</th></tr></thead><tbody><tr><td><code>delete_site</code></td><td>Roughly 16 months of performance history, discarded. Re-adding starts empty</td></tr><tr><td><code>unverify_site</code></td><td>Owner access to the site; every property for it drops to 403, and the Indexing API stops working</td></tr><tr><td><code>update_site_owners</code></td><td>Everyone not in the list you pass. It is the complete owner list afterwards</td></tr><tr><td><code>delete_sitemap</code></td><td>Submission history and error report. The least severe of the four — <code>submit_sitemap</code> puts it back</td></tr></tbody></table><p>A plain boolean <code>confirm</code> parameter would not do. The model could set it on the first call, or be talked into it by instructions hidden in upstream content — and this server hands the model plenty of that.</p><p>Where the client cannot show a dialog, the tool refuses its first call and returns a short-lived, single-use token bound to those exact arguments. That token only ever appears in a <em>previous</em> tool result, so it cannot be guessed — but be clear about what it proves, because this server is: <strong>the call was made twice with the same arguments, and nothing more.</strong> A model can read it out of the first result and quote it back in the same turn. The fallback text says so rather than implying somebody approved, and names whether it was the client that could not be asked or the operator who switched the dialog off with <code>ELICITATION=false</code>.</p><p>Either way the approval is bound to a resource key, so one issued for one property cannot be replayed against another.</p><p>See <a href="/guide/approval">Asking a person</a>.</p><h2 id="untrusted-content" tabindex="-1">Untrusted content <a class="header-anchor" href="#untrusted-content" aria-label="Permalink to “Untrusted content”">​</a></h2><p>Everything the APIs return is marked as untrusted, and &quot;it is only search data&quot; is exactly the wrong intuition:</p><ul><li><strong>Search queries</strong> are strings arbitrary members of the public typed into Google, handed to a model verbatim.</li><li><strong>Page titles, canonical URLs and crawl diagnostics</strong> come from whoever runs the crawled site.</li></ul><p>Someone who wants a model to act on their instructions can put them in a page title and wait to be crawled. Confirmation prompts therefore never quote anything that came from an API — no property label, no page title, nothing.</p><h2 id="credentials-never-reach-the-output" tabindex="-1">Credentials never reach the output <a class="header-anchor" href="#credentials-never-reach-the-output" aria-label="Permalink to “Credentials never reach the output”">​</a></h2><ul><li>Deleted from the environment after start-up, so they are not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</li><li><code>redirect: &#39;error&#39;</code> on every request: a redirect away from Google cannot carry the access token with it.</li><li>A rejected value is described rather than echoed. <code>GSC_REFRESH_TOKEN</code> and <code>GSC_ALLOW_TOOLS</code> are adjacent lines in every compose file, and a paste into the wrong one must not print the secret into the client&#39;s log.</li><li>The startup line names <em>which kind</em> of credential is in use, never the value.</li></ul><h2 id="no-ssrf-guard-on-purpose" tabindex="-1">No SSRF guard, on purpose <a class="header-anchor" href="#no-ssrf-guard-on-purpose" aria-label="Permalink to “No SSRF guard, on purpose”">​</a></h2><p>The sibling servers in this family all carry a <code>hosts.ts</code> that refuses loopback, link-local and cloud-metadata addresses. This one does not, and that is a decision rather than an omission: no target host is configurable here. Every request goes to one of three hard-coded Google endpoints, so there is no attacker-controlled destination to guard against.</p><h2 id="budgets" tabindex="-1">Budgets <a class="header-anchor" href="#budgets" aria-label="Permalink to “Budgets”">​</a></h2><p>A tool result is capped at 100 kB. List results drop <strong>whole entries</strong> rather than slicing the JSON — a truncated document is not a smaller answer, it is an unparseable one — and say how many were dropped and how to narrow the request. A single oversized object has its longest text fields shortened, each marked, so the structure survives.</p><p>The budget counts bytes, not characters. Search queries are the most multilingual free text there is, and a character budget would let through three times what it promises.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Use <a href="https://github.com/ni-c/google-search-console-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a>, never a public issue, and do not include real credentials or property names.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};